import './style.css';
import {createIcons,LayoutDashboard,ChartNoAxesCombined,Wallet,ArrowLeftRight,FileUp,Settings,Plus,ArrowUpRight,ArrowRight,RefreshCw,ChevronLeft,ChevronRight,Download,Upload,ShieldCheck,House,Zap,ShoppingBasket,Coffee,Car,ShoppingBag,HeartPulse,Repeat,Shapes,Check,X,Pencil,Trash2,Search,ChevronDown,FileText,Info,TriangleAlert,Coins,Copy,Eye,CheckCheck,LockKeyhole,Sparkles} from 'lucide';
import {CATEGORIES,PRESETS,TYPES,DEFAULT_FX,freshState,defaultPlan,monthlySummary,portfolioSummary,holdingValue,monthNow,localDate,uid,round,sum,duplicateFlags,validateTransaction,validateState,demoState,parseCSV,csvTransactions,textTransactions,validDate,preserveAmount} from './model.mjs';
const iconSet={LayoutDashboard,ChartNoAxesCombined,Wallet,ArrowLeftRight,FileUp,Settings,Plus,ArrowUpRight,ArrowRight,RefreshCw,ChevronLeft,ChevronRight,Download,Upload,ShieldCheck,House,Zap,ShoppingBasket,Coffee,Car,ShoppingBag,HeartPulse,Repeat,Shapes,Check,X,Pencil,Trash2,Search,ChevronDown,FileText,Info,TriangleAlert,Coins,Copy,Eye,CheckCheck,LockKeyhole,Sparkles};
const KEY='harbour.workspace.v1';
let state=freshState(),storageError='',view='overview',month=monthNow(),assetFilter='all',query='',txType='all',chartAsset='ada',chartRange='1mo',refreshing=false,quoteErrors={},importBusy=false,review=null,csvTable=null,sourceText='',lastFile='',importOptions={currency:'AED',account:'Main account',dateOrder:'DMY',positive:'expense'},toastTimer;
const histories=new Map();let historyBusy=new Set(),realState=null,storageBlocked=false;
try{const saved=localStorage.getItem(KEY);if(saved){const original=JSON.parse(saved);state=validateState(original);state.quotes=original.quotes&&typeof original.quotes==='object'?original.quotes:{};}}catch(e){storageBlocked=true;storageError='Saved data could not be opened. Export or restore a backup in Settings before replacing it.';}
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<i data-lucide="${name}" class="${cls}" aria-hidden="true"></i>`;
const icons=()=>createIcons({icons:iconSet,attrs:{'stroke-width':1.65}});
const cur=()=>state.settings.currency;
const usd=n=>n*(cur()==='AED'?state.settings.fx:1);
const aed=n=>cur()==='USD'?n/state.settings.fx:n;
const toAED=n=>round(cur()==='USD'?n*state.settings.fx:n);
const number=(n,d=2)=>Number(n).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const money=(n,base='AED',d=2)=>`${cur()} ${number(base==='USD'?usd(n):aed(n),d)}`;
const amountInput=n=>String(round(aed(n)));
const percentage=n=>`${n>=0?'+':''}${number(n,2)}%`;
const monthLabel=(m=month)=>new Date(m+'-15T12:00:00').toLocaleDateString('en-GB',{month:'long',year:'numeric'});
const shortDate=s=>new Date(s+'T12:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short'});
const dateTime=s=>{const d=new Date(s);return Number.isNaN(d.getTime())?'Unknown timestamp':d.toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});};
const button=(text,action,ic='',cls='',extra='')=>`<button class="button ${cls}" data-action="${action}" ${extra}>${ic?icon(ic):''}${text}</button>`;
const options=(items,selected)=>items.map(([value,label])=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`).join('');
function notify(text){const t=$('#toast');t.textContent=text;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',5000);}
function persist(){if(state.isDemo)return true;if(storageBlocked){notify(storageError);return false;}try{localStorage.setItem(KEY,JSON.stringify(state));storageError='';return true;}catch{storageError='Changes are only in memory: browser storage is full or unavailable. Export a backup now.';notify(storageError);return false;}}
function titleBlock(eyebrow,title,subtitle,action=''){const back=view==='overview'?'':`<button class="back-overview" data-view="overview" aria-label="Back to Overview">${icon('arrow-left')}<span>Back to Overview</span></button>`;return `<div class="page-intro">${back}<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div></div>`;}
const navItems=[['overview','layout-dashboard','Overview'],['portfolio','chart-no-axes-combined','Portfolio'],['budget','wallet','Monthly budget'],['transactions','arrow-left-right','Transactions'],['import','file-up','Import statements']];
const viewIds=[...navItems.map(([id])=>id),'settings'];
const routeView=()=>viewIds.includes(location.hash.slice(1))?location.hash.slice(1):'overview';
view=routeView();
if(location.hash!==`#${view}`)history.replaceState({view},'',`#${view}`);
function render(){
 const label=[...navItems,['settings','','Settings']].find(n=>n[0]===view)?.[2];
 $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#overview" data-view="overview" aria-label="Harbour overview"><span class="brand-mark">H</span>harbour<span class="brand-dot">.</span></a><div class="workspace-label">PERSONAL WORKSPACE</div><nav aria-label="Main navigation">${navItems.map(([id,ic,name])=>`<button class="nav-link ${view===id?'active':''}" data-view="${id}" ${view===id?'aria-current="page"':''}>${icon(ic)}<span>${name}</span>${id==='import'&&review?'<span class="nav-count">'+review.rows.length+'</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom">${icon('shield-check','privacy-icon')}<b>A little clarity.<br>A lot of possibility.</b><p>Saved in this browser.<br>Your workspace stays yours.</p><button class="nav-link settings-nav ${view==='settings'?'active':''}" data-view="settings">${icon('settings')}<span>Settings & backup</span></button><div class="profile"><span class="avatar">Y</span><div><b>Your workspace</b><small>PRIVATE · ON THIS DEVICE</small></div></div></div></aside><main><header class="topbar"><nav class="breadcrumb" aria-label="Breadcrumb"><button data-view="overview">Workspace</button><span class="breadcrumb-slash">/</span><b aria-current="page">${label}</b></nav><div class="top-meta"><span class="device-label">${icon('lock-keyhole')} LOCAL WORKSPACE</span><div class="currency-switch" role="group" aria-label="Display currency">${['AED','USD'].map(c=>`<button data-currency="${c}" class="${cur()===c?'selected':''}" aria-pressed="${cur()===c}">${c}</button>`).join('')}</div><button class="icon-button mobile-settings" data-view="settings" aria-label="Settings">${icon('settings')}</button></div></header><div class="content">${storageError?`<div class="notice error">${icon('triangle-alert')}${esc(storageError)}</div>`:''}${state.isDemo?`<div class="demo-banner"><span>EXAMPLE WORKSPACE</span>These balances and transactions are illustrative. Your personal data is separate.<button class="text-button" data-action="exit-demo">Back to my workspace ${icon('arrow-right')}</button></div>`:''}${({overview:overview,portfolio:portfolio,budget:budget,transactions:transactions,import:importView,settings:settings}[view])()}<footer><b>HARBOUR</b><span>Your money, in perspective.</span><span>${state.isDemo?'Illustrative data · Demo mode':`Local workspace · ${cur()==='AED'?'1 USD = '+number(state.settings.fx,4)+' AED':'USD display · budget records stored in AED'}`}</span></footer></div></main>`;
 icons();if(['overview','portfolio'].includes(view))ensureHistory();
}
function stat(label,value,foot,{dark=false,detail='',action=''}={}){return `<article class="stat-card ${dark?'dark':''}"><div class="stat-label">${label}${action?`<button class="icon-button" data-action="${action}" aria-label="${label} details">${icon('arrow-up-right')}</button>`:''}</div><h2><small>${cur()}</small> ${number(value,0)}</h2><div class="stat-foot">${foot}</div>${detail}</article>`;}
function monthPicker(){return `<div class="month-picker"><button class="icon-button" data-action="prev-month" aria-label="Previous month">${icon('chevron-left')}</button><input type="month" id="month-select" value="${month}" aria-label="Selected budget month"><button class="icon-button" data-action="next-month" aria-label="Next month">${icon('chevron-right')}</button></div>`;}
function overview(){
 const p=portfolioSummary(state),b=monthlySummary(state,month),gain=p.returnPct==null?'Add purchase costs to track your return':`<span class="${p.gain>=0?'positive-pill':'negative-pill'}">${percentage(p.returnPct)}</span> unrealized · known purchase costs`;
 return titleBlock('THE BIG PICTURE','Make room for what’s next.','Your assets, your spending, a clearer way forward.',button('Add holding','add-holding','plus','primary'))+
 (!state.isDemo&&!state.holdings.some(h=>h.quantity>0)?`<div class="welcome-banner"><div>${icon('sparkles')}<b>Your watchlist is ready.</b> Add your token quantities to make it your portfolio.</div><button class="text-button" data-action="demo">Explore an example ${icon('arrow-right')}</button></div>`:'')+
 `<section class="stats">${stat(p.missing?'Portfolio · partial value':'Total portfolio',usd(p.total),gain,{dark:true,action:'go-portfolio',detail:`<div class="mini-bars">${Array.from({length:28},(_,i)=>`<i style="height:${15+(i*17%25)+i*1.2}px"></i>`).join('')}</div>`})}${stat('Spent this month',aed(b.spent),`${monthLabel()} · ${money(b.planned,'AED',0)} planned`,{action:'go-budget',detail:`<div class="progress"><i style="width:${b.planned?Math.min(100,Math.max(0,b.spent/b.planned*100)):0}%;${b.spent>b.planned?'background:var(--red)':''}"></i></div>`})}${stat('Room to invest · forecast',aed(b.room),b.hasPlan?'After remaining expenses, reserves & investments':'Set your income, expenses & reserve to begin',{action:'edit-plan',detail:`<div class="subtle-note">${b.hasPlan?'Based on planned income, not your bank balance.':'A thoughtful plan starts with your monthly budget.'}</div>`})}</section>
 <div class="dashboard-grid">${marketChart()}${allocation(p)}</div>
 <section class="panel holdings-panel"><div class="panel-heading"><div><h3>Your holdings</h3><p>Every asset. One considered view.</p></div><button class="text-button" data-view="portfolio">View portfolio ${icon('arrow-right')}</button></div>${holdingsTable(state.holdings)}</section>
 <div class="dashboard-grid lower-grid"><section class="panel"><div class="panel-heading"><div><h3>This month, in focus</h3><p>${monthLabel()} · planned vs. actual</p></div><button class="text-button" data-view="budget">Open budget ${icon('arrow-right')}</button></div>${budgetBars(b,4)}</section><section class="panel next-step"><div class="eyebrow">A GOOD NEXT STEP</div><h3>${b.hasPlan?'Bring your spending into focus.':'Give your income a plan.'}</h3><p>${b.hasPlan?'Import your statement, check the categories, and see how the month is really taking shape.':'Set your monthly take-home pay, expected bills, and a reserve for the things that don’t happen every month.'}</p>${button(b.hasPlan?'Import a statement':'Plan my month',b.hasPlan?'go-import':'edit-plan',b.hasPlan?'file-up':'arrow-right')}</section></div>`;
}
function allocation(p){const colors={crypto:'#253c59',etf:'#98b9a6',gold:'#c9ae72'},names={crypto:'Crypto',etf:'ETFs',gold:'24k gold'};let offset=0;const segments=Object.entries(p.allocation).map(([k,v])=>{let start=offset;offset+=p.total?v/p.total*100:0;return `${colors[k]} ${start}% ${offset}%`;}).join(',');return `<section class="panel allocation-panel"><div class="panel-heading"><div><h3>Asset allocation</h3><p>${p.total?'Where your portfolio stands.':'Your mix will take shape here.'}</p></div>${icon('shapes','muted')}</div><div class="donut" style="--segments:${p.total?segments:'#edf0f3 0 100%'}" role="img" aria-label="${Object.entries(p.allocation).map(([k,v])=>`${names[k]} ${p.total?number(v/p.total*100,1):0}%`).join(', ')}"><div><small>${p.total?'invested across':'Ready for'}</small><strong>${p.total?Object.values(p.allocation).filter(x=>x>0).length:'3'}</strong><small>asset classes</small></div></div><div class="allocation-legend">${Object.entries(p.allocation).map(([k,v])=>`<div><span><i style="background:${colors[k]}"></i>${names[k]}</span><b>${p.total?number(v/p.total*100,1):'0'}%</b><small>${money(v,'USD',0)}</small></div>`).join('')}</div>${p.missing?'<p class="form-hint negative">Unpriced holdings are excluded.</p>':''}</section>`;}
function marketChart(){
 const available=state.holdings.filter(h=>h.type!=='gold');if(!available.find(h=>h.id===chartAsset))chartAsset=available[0]?.id;
 const h=available.find(h=>h.id===chartAsset),key=`${h?.marketSymbol||h?.symbol}:${chartRange}`,hist=state.isDemo?{points:Array.from({length:42},(_,i)=>({time:Date.now()-(41-i)*86400000,value:.20+i*.0012+Math.sin(i*1.7)*.007})),source:'Illustrative example'}:histories.get(key),pts=hist?.points||[],first=pts[0]?.value,last=pts.at(-1)?.value;
 const d=pts.length>1?lineChart(pts):`<div class="chart-empty">${icon(hist?.error?'triangle-alert':'chart-no-axes-combined')}<b>${hist?.error?'History unavailable':h?'Loading market history…':'Add an asset to see its history'}</b><span>${hist?.error?esc(hist.error):'Daily closing prices. Your portfolio value is shown above.'}</span>${hist?.error?'<button class="text-button" data-action="retry-history">Try again</button>':''}</div>`;
 return `<section class="panel portfolio-panel"><div class="panel-heading"><div><h3>Market pulse</h3><p>${state.isDemo?'Illustrative price history':'Daily market prices · not portfolio performance'}</p></div><select id="chart-asset" class="compact-select" aria-label="Chart asset">${options(available.map(h=>[h.id,h.symbol]),chartAsset)}</select></div><div class="chart-toolbar"><div class="chart-value">${last!=null?money(last,'USD',last<1?4:2):'—'} ${first?`<span class="${last>=first?'positive':'negative'}">${percentage((last/first-1)*100)}</span>`:''}</div><div class="segmented small" aria-label="Chart period">${[['1mo','1M'],['3mo','3M'],['1y','1Y']].map(([v,l])=>`<button data-range="${v}" class="${chartRange===v?'selected':''}" aria-pressed="${chartRange===v}">${l}</button>`).join('')}</div></div>${d}<div class="chart-source">${esc(hist?.source||'Yahoo Finance')} ${pts.length?'· '+shortDate(localDate(new Date(pts.at(-1).time)))+' · latest bar may be in progress':''}</div></section>`;
}
function lineChart(pts){const vals=pts.map(p=>usd(p.value)),min=Math.min(...vals),max=Math.max(...vals),pad=(max-min)*.12||max*.05||1,low=min-pad,high=max+pad;const xy=pts.map((p,i)=>[i/(pts.length-1)*680,180-(usd(p.value)-low)/(high-low)*170]);const path=xy.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(2)},${y.toFixed(2)}`).join(' ');const labels=[0,Math.floor(pts.length/3),Math.floor(pts.length*2/3),pts.length-1];return `<div class="chart-wrap"><div class="chart-y"><span>${number(high,high<1?3:2)}</span><span>${number((low+high)/2,high<1?3:2)}</span><span>${number(low,high<1?3:2)}</span></div><svg class="main-chart" viewBox="0 0 680 200" preserveAspectRatio="none" role="img" aria-label="Daily ${esc(chartAsset)} market prices from ${shortDate(localDate(new Date(pts[0].time)))} to ${shortDate(localDate(new Date(pts.at(-1).time)))}"><defs><linearGradient id="chartfill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#4f987c" stop-opacity=".19"/><stop offset="1" stop-color="#4f987c" stop-opacity="0"/></linearGradient></defs><path d="${path} L680,200 L0,200 Z" fill="url(#chartfill)"/><path d="${path}" fill="none" stroke="#38846b" stroke-width="2.6" vector-effect="non-scaling-stroke"/>${xy.map(([x,y],i)=>`<circle class="chart-point" cx="${x}" cy="${y}" r="5"><title>${shortDate(localDate(new Date(pts[i].time)))}: ${money(pts[i].value,'USD',4)}</title></circle>`).join('')}</svg></div><div class="chart-axis">${labels.map(i=>`<span>${shortDate(localDate(new Date(pts[i].time)))}</span>`).join('')}</div>`;}
async function ensureHistory(){if(state.isDemo)return;const h=state.holdings.find(h=>h.id===chartAsset);if(!h)return;const symbol=h.marketSymbol||h.symbol,key=`${symbol}:${chartRange}`;if(histories.has(key)||historyBusy.has(key))return;historyBusy.add(key);try{const r=await fetch(`/api/history?symbol=${encodeURIComponent(symbol)}&range=${chartRange}`);const data=await r.json();if(!r.ok)throw new Error(data.error);histories.set(key,data);}catch(e){histories.set(key,{error:e.message,points:[]});}finally{historyBusy.delete(key);if(['overview','portfolio'].includes(view)&&!$('#modal-root dialog')&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))render();}}
function quoteStatus(h,v){if(h.manualUSD!=null)return '<span class="status-label manual">Manual quote</span>';if(!v.quote)return `<span class="status-label unavailable">${quoteErrors[h.id]?'Unavailable':'Awaiting quote'}</span>`;const old=Date.now()-new Date(v.quote.asOf).getTime()>((h.type==='etf')?96*3600000:3600000);return `<span class="status-label ${quoteErrors[h.id]||old?'unavailable':''}" title="${esc(quoteErrors[h.id]||v.quote.source)}">${state.isDemo?'Example':quoteErrors[h.id]?'Cached · refresh failed':old?'Older quote':h.type==='etf'?'Last trade':'Latest quote'} · ${dateTime(v.quote.asOf)}</span>`;}
function holdingsTable(holdings){return `<div class="table-wrap"><table class="holdings-table"><thead><tr><th>Asset</th><th>Price <small>${cur()}</small></th><th>Change <small>24h / session</small></th><th>Holdings</th><th>Value <small>${cur()}</small></th><th aria-label="Edit holding"></th></tr></thead><tbody>${holdings.length?holdings.map(h=>{const v=holdingValue(h,state.quotes),change=h.manualUSD==null?v.quote?.change24h:null;return `<tr><td><div class="asset-cell"><span class="asset-icon ${h.type}" style="--asset-color:${esc(h.color||'#536d92')}">${esc(h.mark||h.symbol.slice(0,2))}</span><div><b>${esc(h.name)}</b><small>${esc(h.symbol)} · ${h.type==='gold'?'24k · per gram':h.type==='crypto'?'Crypto':'ETF'}</small></div></div></td><td><b>${v.price==null?'—':number(usd(v.price),v.price<1?4:2)}</b>${quoteStatus(h,v)}</td><td class="${change==null?'muted':change>=0?'positive':'negative'}">${change==null?'—':percentage(change)}${h.type==='gold'&&v.quote?.changeBasis?`<small title="${esc(dateTime(v.quote.changeFrom))}">Since prior quote</small>`:''}</td><td>${h.quantity?number(h.quantity,h.type==='gold'?2:Math.min(6,(String(h.quantity).split('.')[1]||'').length))+(h.type==='gold'?' g':''):`<button class="text-button" data-edit-holding="${esc(h.id)}">Add quantity</button>`}</td><td><b>${v.value==null?'—':number(usd(v.value),2)}</b>${v.cost!=null&&v.value!=null?`<small class="${v.value>=v.cost?'positive':'negative'}">${money(v.value-v.cost,'USD')} P/L</small>`:''}</td><td><button class="icon-button" data-edit-holding="${esc(h.id)}" aria-label="Edit ${esc(h.name)}">${icon('pencil')}</button></td></tr>`;}).join(''):'<tr><td colspan="6" class="empty-cell">No holdings in this asset class. Add one to get started.</td></tr>'}</tbody></table></div>`;}
function portfolio(){const p=portfolioSummary(state);return titleBlock('YOUR ASSETS, TOGETHER','A clearer view of your wealth.','Track your crypto, ETFs, and 24k gold in one place.',`<div class="heading-actions">${button(refreshing?'Refreshing…':'Refresh prices','refresh','refresh-cw','',refreshing?'disabled':'')}${button('Add holding','add-holding','plus','primary')}</div>`)+`<section class="stats">${stat(p.missing?'Portfolio · partial value':'Portfolio value',usd(p.total),`${state.holdings.filter(h=>h.quantity>0).length} holdings with a quantity`,{dark:true})}${stat('Purchase cost · priced holdings',usd(p.cost),p.unknownCost?`${p.unknownCost} holding(s) still need purchase costs`:'Average purchase price × current quantity')}${stat('Unrealized gain / loss',usd(p.gain),p.returnPct!=null?`<span class="${p.gain>=0?'positive':'negative'}">${percentage(p.returnPct)}</span> on holdings with a known cost`:'Add your average purchase costs to track returns')}</section>${Object.keys(quoteErrors).length?`<div class="notice">${icon('info')}Some prices could not refresh. Last-known quotes remain labelled as cached; you can also enter a manual price.</div>`:''}<div class="dashboard-grid">${marketChart()}${allocation(p)}</div><section class="panel holdings-panel"><div class="panel-heading"><div><h3>Holdings & watchlist</h3><p>Zero quantity keeps an asset on your watchlist.</p></div><div class="segmented">${[['all','All assets'],['crypto','Crypto'],['etf','ETFs'],['gold','Gold']].map(([v,l])=>`<button class="${assetFilter===v?'selected':''}" data-filter="${v}" aria-pressed="${assetFilter===v}">${l}</button>`).join('')}</div></div>${holdingsTable(state.holdings.filter(h=>assetFilter==='all'||h.type===assetFilter))}</section><div class="source-note">${icon('info')}Gold uses the spot value of pure gold, excluding dealer premiums, making charges, and selling fees. Crypto: CoinGecko. ETFs: Yahoo Finance, delayed or last trade. Prices refresh every 5 minutes while this page is open.</div>`;}
function budgetBars(b,limit=9){const categories=[...CATEGORIES].sort((a,c)=>(b.plan.categories[c.id]||0)-(b.plan.categories[a.id]||0)).slice(0,limit);if(!b.hasPlan&&!b.rows.length)return `<div class="empty compact">${icon('wallet')}<h4>Your month is a blank canvas.</h4><p>Start with your income and a plan for each category.</p>${button('Set up budget','edit-plan','plus')}</div>`;return `<div class="budget-bars">${categories.map(c=>{const planned=b.plan.categories[c.id]||0,actual=b.actual[c.id]||0,pct=planned?Math.min(100,Math.max(0,actual/planned*100)):actual>0?100:0;return `<div class="budget-bar"><div><span>${icon(c.icon)}${c.name}</span><span><b class="${actual>planned?'negative':''}">${money(actual,'AED',0)}</b><small> / ${money(planned,'AED',0)}</small></span></div><div class="progress"><i style="width:${pct}%;background:${actual>planned?'#bf7276':c.color}"></i></div></div>`;}).join('')}</div>`;}
function budget(){const b=monthlySummary(state,month);return titleBlock('A PLAN FOR THE EVERYDAY','Give every month some direction.','Set your plan, track the reality, and keep your next move in sight.',monthPicker())+`<section class="stats">${stat('Planned take-home income',aed(b.plan.income),`${money(b.income,'AED',0)} recorded as received`,{dark:true,action:'edit-plan'})}${stat('Actual spending',aed(b.spent),`${money(b.planned,'AED',0)} planned across ${CATEGORIES.length} categories`,{action:'go-transactions'})}${stat('Room to invest · forecast',aed(b.room),'Planned income less projected spending & reserves',{action:'edit-plan'})}</section><div class="budget-layout"><section class="panel"><div class="panel-heading"><div><h3>Plan meets reality</h3><p>${monthLabel()} · all amounts in ${cur()}</p></div><div class="heading-actions">${button('Copy previous','copy-plan','copy')}${button('Edit plan','edit-plan','pencil','primary')}</div></div><div class="budget-table table-wrap"><table><thead><tr><th>Category</th><th>Planned</th><th>Actual</th><th>Remaining</th></tr></thead><tbody>${CATEGORIES.map(c=>{const plan=b.plan.categories[c.id]||0,actual=b.actual[c.id]||0,left=plan-actual;return `<tr><td><div class="category-cell"><span class="category-icon" style="color:${c.color};background:${c.color}16">${icon(c.icon)}</span>${c.name}</div><div class="progress"><i style="width:${plan?Math.min(100,Math.max(0,actual/plan*100)):actual>0?100:0}%;background:${left<0?'#bb737a':c.color}"></i></div></td><td>${number(aed(plan),0)}</td><td>${number(aed(actual),0)}</td><td class="${left<0?'negative':'muted'}">${number(aed(left),0)}${left<0?'<small>over plan</small>':''}</td></tr>`;}).join('')}</tbody><tfoot><tr><td>Total spending</td><td>${number(aed(b.planned),0)}</td><td>${number(aed(b.spent),0)}</td><td class="${b.planned-b.spent<0?'negative':''}">${number(aed(b.planned-b.spent),0)}</td></tr></tfoot></table></div></section><div class="stack"><section class="panel runway"><div class="eyebrow">LOOKING AHEAD</div><h3>Your investment runway</h3><div class="runway-total ${b.room<0?'negative':''}">${money(b.room,'AED',0)}</div><p>Forecast for ${monthLabel()}. This is a planning estimate, not your available bank balance.</p><div class="calculation"><div><span>Planned income</span><b>${money(b.plan.income,'AED',0)}</b></div><div><span>Spent so far</span><b>− ${money(b.spent,'AED',0)}</b></div><div><span>Unspent category budgets</span><b>− ${money(b.remaining,'AED',0)}</b></div><div><span>Cash & irregular-bill reserve</span><b>− ${money(b.plan.reserve,'AED',0)}</b></div><div><span>Already invested</span><b>− ${money(b.invested,'AED',0)}</b></div></div><div class="runway-note">${icon('info')}Overspending lowers this forecast. Unused budgets stay reserved until you revise your plan.</div></section><section class="panel"><h3>Make the next month smarter.</h3><p class="body-copy">Review your statement, adjust categories that need it, then copy your plan into the next month. Set aside monthly amounts for annual bills in your reserve.</p>${button('Import statement','go-import','file-up')}</section></div></div>`;}
function filteredTransactions(){return state.transactions.filter(t=>t.date.startsWith(month)&&(txType==='all'||t.type===txType)&&`${t.description} ${t.account} ${CATEGORIES.find(c=>c.id===t.category)?.name}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));}
function transactions(){const rows=filteredTransactions(),b=monthlySummary(state,month);return titleBlock('THE DETAILS THAT ADD UP','Follow your money.','Review and categorise what came in, what went out, and what moved.',button('Add transaction','add-transaction','plus','primary'))+`<section class="panel transaction-panel"><div class="transaction-toolbar"><div class="search-field">${icon('search')}<input id="transaction-search" value="${esc(query)}" placeholder="Search merchant or category" aria-label="Search transactions"></div>${monthPicker()}<select id="transaction-type" class="compact-select" aria-label="Transaction type">${options([['all','All types'],...Object.entries(TYPES)],txType)}</select>${button('Export','export-csv','download')}</div><div class="transaction-summary"><span><b>${rows.length}</b> transactions shown</span><span>Income received <b class="positive">${money(b.income)}</b></span><span>Net spending <b>${money(b.spent)}</b></span></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Transaction</th><th>Category</th><th>Type</th><th>Amount <small>${cur()}</small></th><th></th></tr></thead><tbody>${rows.length?rows.map(t=>`<tr><td class="nowrap">${shortDate(t.date)}</td><td><b>${esc(t.description)}</b><small>${esc(t.account)} · ${esc(t.source||'Manual')}</small></td><td><span class="category-tag">${CATEGORIES.find(c=>c.id===t.category)?.name||'Other'}</span></td><td><span class="type-tag ${t.type}">${TYPES[t.type]}</span></td><td class="amount-cell ${['income','refund'].includes(t.type)?'positive':''}">${['income','refund'].includes(t.type)?'+':'−'}${number(aed(t.amount))}</td><td><button class="icon-button" data-edit-transaction="${t.id}" aria-label="Edit ${esc(t.description)}">${icon('pencil')}</button></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty">${icon('arrow-left-right')}<h4>${query?'No matching transactions.':'A fresh page for '+monthLabel()+'.'}</h4><p>${query?'Try another merchant, category, or transaction type.':'Add an expense or import a statement to see your actual spending.'}</p>${!query?button('Import a statement','go-import','file-up'):''}</div></td></tr>`}</tbody></table></div></section>`;}
function importView(){return titleBlock('FROM STATEMENT TO CLARITY','Bring your spending into focus.','Read locally. Review carefully. Add only when you’re ready.')+`<div class="import-steps"><span class="active"><i>1</i> Choose a statement</span><b>—</b><span class="${review?'active':''}"><i>2</i> Review transactions</span><b>—</b><span><i>3</i> Update your budget</span></div>${review?reviewView():`<div class="import-layout"><section class="panel"><label class="drop-zone ${importBusy?'busy':''}" id="drop-zone" for="statement-file">${icon('file-up')}<h3>${importBusy?'Reading your statement…':'Drop a statement. Find the story.'}</h3><p>PDF, screenshots, or a bank CSV export</p><span class="button primary">${icon('plus')} Choose a file</span><small>PDF, PNG, JPG, WEBP, CSV · up to 20 MB</small><input type="file" id="statement-file" accept=".pdf,.png,.jpg,.jpeg,.webp,.csv,.txt" ${importBusy?'disabled':''}></label><p id="import-progress" class="form-hint" role="status" aria-live="polite"></p><div class="import-options"><label>Statement currency<select id="import-currency">${options([['AED','AED — UAE dirham'],['USD','USD — US dollar']],importOptions.currency)}</select></label><label>Account nickname<input id="import-account" value="${esc(importOptions.account)}" maxlength="120" placeholder="e.g. Main account"></label><label>Date format<select id="import-date">${options([['DMY','Day / month / year'],['MDY','Month / day / year']],importOptions.dateOrder)}</select></label></div><details class="paste-details"><summary>Have extracted text instead?</summary><p class="form-hint">Paste statement text or a CSV table from a conversation. Include a full date, description, and amount on each line.</p><textarea id="statement-text" rows="7" placeholder="2026-09-05 Carrefour groceries 245.50">${esc(sourceText)}</textarea>${button('Prepare for review','parse-text','arrow-right')}</details></section><div class="stack"><section class="panel import-guidance"><div class="eyebrow">A BETTER MONTHLY ROUTINE</div><h3>A few minutes. More perspective.</h3><ol><li><b>Start with the plan.</b><p>Set your take-home income, spending categories, and reserve.</p></li><li><b>Bring in the actuals.</b><p>CSV is the most reliable. PDF and screenshot reading works best with clear English statements.</p></li><li><b>Check before adding.</b><p>Confirm amounts and debit/credit direction. Mark transfers and investments separately.</p></li><li><b>Close the loop.</b><p>Compare with your plan, then adjust the next month.</p></li></ol></section><div class="privacy-card">${icon('shield-check')}<div><b>Your statement stays on this device.</b><p>Text extraction runs in your browser. Original files aren’t saved or uploaded. Only transactions you approve are retained.</p></div></div></div></div>`}${state.imports.length?`<section class="panel import-history"><div class="panel-heading"><h3>Import history</h3></div>${state.imports.slice().reverse().slice(0,8).map(i=>`<div class="import-history-row">${icon('file-text')}<div><b>${esc(i.name)}</b><small>${dateTime(i.at)}</small></div><span>${i.count} transactions added</span></div>`).join('')}</section>`:''}`;}
function reviewView(){const flags=duplicateFlags(review.rows,state.transactions),selected=review.rows.filter(r=>r.include!==false),total=sum(selected.filter(r=>r.type==='expense').map(r=>r.amount))-sum(selected.filter(r=>r.type==='refund').map(r=>r.amount));return `<section class="panel review-panel"><div class="panel-heading"><div><h3>Review your transactions</h3><p>${esc(lastFile||'Pasted text')} · ${review.rows.length} candidates · amounts shown in ${cur()}</p></div>${button('Discard review','discard-review','x')}</div>${csvTable?csvMapping():''}<div class="notice">${icon('info')}Statement layouts differ. Check each amount, date, and type against the original. For PDF/images, the first amount on a line is suggested; a balance can be mistaken for a charge.</div>${review.issues.length?`<details class="import-issues"><summary>${review.issues.length} line(s) need manual attention</summary><ul>${review.issues.slice(0,100).map(i=>`<li>${esc(i)}</li>`).join('')}</ul><p>Add any missing charges with “Add review row”.</p></details>`:''}<div class="review-actions">${button('Add review row','add-review-row','plus')}${button('Mark included rows checked','check-review','check-check')}<span class="muted">${flags.filter(Boolean).length} possible duplicates · excluded by default</span></div><div class="table-wrap"><table class="review-table"><thead><tr><th>Include</th><th>Date</th><th>Description</th><th>Amount ${cur()}</th><th>Type</th><th>Category</th><th>Checked</th></tr></thead><tbody>${review.rows.map((t,i)=>`<tr class="${t.include===false?'excluded':''}"><td><input type="checkbox" data-review="${i}" data-field="include" ${t.include!==false?'checked':''} aria-label="Include transaction ${i+1}">${flags[i]?'<small class="negative">Possible duplicate</small>':''}</td><td><input type="date" data-review="${i}" data-field="date" value="${esc(t.date)}" aria-label="Date row ${i+1}"></td><td><input data-review="${i}" data-field="description" value="${esc(t.description)}" maxlength="500" aria-label="Description row ${i+1}">${t.rawLine?`<details><summary>Source line</summary><span class="raw-line">${esc(t.rawLine)}</span></details>`:''}</td><td><input type="number" min="0.01" step="0.01" data-review="${i}" data-field="amount" value="${amountInput(t.amount)}" aria-label="Amount row ${i+1}"></td><td><select data-review="${i}" data-field="type" aria-label="Type row ${i+1}">${options(Object.entries(TYPES),t.type)}</select></td><td><select data-review="${i}" data-field="category" aria-label="Category row ${i+1}">${options(CATEGORIES.map(c=>[c.id,c.name]),t.category)}</select></td><td><input type="checkbox" data-review="${i}" data-field="reviewed" ${t.reviewed?'checked':''} aria-label="Verified row ${i+1}"></td></tr>`).join('')}</tbody></table></div>${!review.rows.length?'<div class="empty compact"><h4>No transactions could be identified.</h4><p>Try a CSV export or add the missing rows manually. Nothing has been added to your budget.</p></div>':''}<div class="review-footer"><div><b>${selected.length} included · ${money(total)} net spending</b><small>Income, transfers, and investments are treated separately.</small></div>${button('Add checked transactions','commit-import','check','primary',selected.length?'':'disabled')}</div></section>`;}
function csvMapping(){const headers=csvTable[0]||[],m=review.mapping;return `<details class="mapping" open><summary>Match the CSV columns</summary><div class="mapping-grid">${[['date','Date'],['description','Description'],['amount','Amount'],['debit','Debit / money out'],['credit','Credit / money in']].map(([key,label])=>`<label>${label}<select data-map="${key}">${options([['-1','Not used'],...headers.map((h,i)=>[String(i),h||'Column '+(i+1)])],String(m[key]))}</select></label>`).join('')}<label>Positive amount means<select id="positive-direction">${options([['expense','Expense / debit'],['income','Income / credit']],importOptions.positive)}</select></label></div><p class="form-hint">Use Amount alone, or Debit and Credit columns. Dates use ${importOptions.dateOrder==='DMY'?'day / month / year':'month / day / year'}. Rebuilding replaces review edits.</p>${button('Rebuild preview','remap','refresh-cw')}</details>`;}
function settings(){return titleBlock('YOUR WORKSPACE','Make yourself at home.','Manage your display, data, and the way Harbour works for you.')+`<div class="settings-grid"><section class="panel"><h3>Display & prices</h3><form id="settings-form"><label>Display currency<select name="currency">${options([['AED','AED — UAE dirham'],['USD','USD — US dollar']],cur())}</select></label><label>AED per 1 USD<input name="fx" type="number" min="0.0001" max="100" step="0.0001" required value="${state.settings.fx}"></label><p class="form-hint">Default planning rate: 3.6725. Currency switching converts the display, not your historical transaction amounts. Bank FX fees can differ.</p><label class="checkbox-label"><input name="autoRefresh" type="checkbox" ${state.settings.autoRefresh?'checked':''}> Refresh prices every 5 minutes while open</label><button class="button primary" type="submit">Save preferences</button></form></section><section class="panel"><h3>Your data, under your control.</h3><p class="body-copy">Your workspace is stored in this browser on this computer. Clearing browser data or using a different browser creates a separate workspace.</p><div class="settings-actions">${button('Export full backup','backup','download','primary')}<label class="button">${icon('upload')} Restore backup<input type="file" id="restore-file" accept=".json" hidden></label>${button('Explore example workspace','demo','eye')}</div><p class="form-hint">Backups include holdings, plans, and transactions. They are readable JSON files; keep them somewhere private. Original statements are never retained.</p></section><section class="panel"><h3>Market data, with context.</h3><div class="source-list"><div><b>Crypto</b><p><a href="https://docs.coingecko.com/reference/simple-price" target="_blank" rel="noreferrer">CoinGecko</a> · public USD quotes and 24-hour change.</p></div><div><b>ETFs</b><p><a href="https://finance.yahoo.com/" target="_blank" rel="noreferrer">Yahoo Finance</a> · USD-listed ETF last trades and historical closes. This public feed is unofficial and may be delayed or unavailable.</p></div><div><b>24k gold</b><p><a href="https://gold-api.com/docs" target="_blank" rel="noreferrer">Gold API</a> · USD spot per troy ounce, divided by 31.1034768 for a gram. No retail premium or selling fee included.</p></div><div><b>When a feed fails</b><p>The last known quote keeps its original timestamp. An unavailable asset is excluded from the portfolio total. You can enter a manual price at any time.</p></div></div></section><section class="panel"><h3>A considered budgeting routine.</h3><p class="body-copy">Plan with take-home income. Reserve enough for remaining bills and irregular expenses. Reconcile actual spending before revising your next month.</p><p class="body-copy">“Room to invest” is a forecast using planned income. It does not verify your bank balance, debts, emergency fund, or whether an investment suits you.</p><a class="text-button" href="https://www.consumerfinance.gov/archive/blog/budgeting-how-to-create-a-budget-and-stick-with-it/" target="_blank" rel="noreferrer">Read the CFPB budgeting guide ${icon('arrow-up-right')}</a><div class="danger-zone"><h4>Start a clean workspace</h4><p>Remove your stored transactions, plans, and holdings from this browser.</p>${button('Reset workspace','reset','trash-2','danger')}</div></section></div>`;}
let lastFocus;
function modal(title,body,onSubmit){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<dialog class="modal" aria-labelledby="modal-title"><div class="modal-heading"><div><div class="eyebrow">HARBOUR WORKSPACE</div><h2 id="modal-title">${title}</h2></div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('x')}</button></div>${body}</dialog>`;const d=$('dialog');d.showModal();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});d.addEventListener('cancel',e=>{e.preventDefault();closeModal();});const f=d.querySelector('form');if(f&&onSubmit)f.addEventListener('submit',e=>{e.preventDefault();if(f.reportValidity())try{onSubmit(Object.fromEntries(new FormData(f)),f);}catch(error){let p=d.querySelector('.form-error');if(!p){p=document.createElement('p');p.className='form-error';p.setAttribute('role','alert');f.prepend(p);}p.textContent=error.message;}});icons();}
function closeModal(){$('dialog')?.close();$('#modal-root').innerHTML='';lastFocus?.focus();}
function holdingModal(id){const existing=state.holdings.find(h=>h.id===id),h=existing||{name:'',symbol:'',type:'crypto',providerId:'',quantity:0,costUSD:null,manualUSD:null};modal(existing?'Edit '+esc(h.name):'Add a holding',`<form id="holding-form"><div class="form-grid"><label>Asset class<select name="type" id="holding-type">${options([['crypto','Cryptocurrency'],['etf','ETF'],['gold','24k physical gold']],h.type)}</select></label><label>Display name<input name="name" required maxlength="120" value="${esc(h.name)}" placeholder="e.g. Vanguard S&P 500"></label><label>Ticker / symbol<input name="symbol" required maxlength="25" pattern="[A-Za-z0-9.^=_-]+" value="${esc(h.symbol)}" placeholder="e.g. VOO"></label><label id="provider-field">CoinGecko coin ID<input name="providerId" value="${esc(h.providerId||'')}" pattern="[a-z0-9-]*" placeholder="e.g. cardano"><span class="form-hint">Coin ID, not ticker. FLUX uses zelcash.</span></label><label><span id="quantity-label">${h.type==='gold'?'Weight in grams':'Quantity / units'}</span><input name="quantity" required type="number" min="0" max="1000000000000000" step="any" value="${h.quantity}"></label><label>Average cost / ${h.type==='gold'?'gram':'unit'} (${cur()})<input name="cost" type="number" min="0" max="1000000000000" step="any" value="${h.costUSD==null?'':Number(usd(h.costUSD).toPrecision(12))}" placeholder="Optional"></label><label class="full">Manual price / ${h.type==='gold'?'gram':'unit'} (${cur()})<input name="manual" type="number" min="0.00000001" max="1000000000000" step="any" value="${h.manualUSD==null?'':usd(h.manualUSD)}" placeholder="Leave blank to use the price feed"><span class="form-hint">Manual prices override the feed and are labelled. ETFs need an exact USD exchange ticker; gold uses pure 24k spot per gram.</span></label></div>${existing&&quoteErrors[h.id]?`<p class="form-hint negative">${esc(quoteErrors[h.id])}</p>`:''}<div class="modal-actions">${existing?`<button type="button" class="button danger" data-delete-holding="${esc(id)}">${icon('trash-2')} Remove</button>`:'<span></span>'}<button class="button primary" type="submit">Save holding</button></div></form>`,data=>{const type=data.type;if(type==='crypto'&&!data.providerId.trim()&&data.manual==='')throw new Error('Enter a CoinGecko ID or a manual quote for this cryptocurrency.');const item={...h,id:existing?.id||uid(),name:data.name.trim(),symbol:data.symbol.trim().toUpperCase(),type,providerId:type==='gold'?'XAU':data.providerId.trim(),quantity:Number(data.quantity),costUSD:data.cost===''?null:preserveAmount(data.cost,h.costUSD,h.costUSD==null?'':Number(usd(h.costUSD).toPrecision(12)),n=>n/(cur()==='AED'?state.settings.fx:1)),manualUSD:data.manual===''?null:Number(data.manual)/(cur()==='AED'?state.settings.fx:1),mark:type==='gold'?'Au':data.symbol.slice(0,2).toUpperCase(),color:h.color||'#5c7b95'};if(!item.name)throw new Error('Enter a display name.');if(type!==h.type||item.symbol!==h.symbol){delete item.marketSymbol;delete state.quotes[item.id];}if(type==='crypto'&&!item.marketSymbol)item.marketSymbol=item.symbol+'-USD';if(existing)state.holdings=state.holdings.map(x=>x.id===id?item:x);else state.holdings.push(item);persist();closeModal();render();notify('Holding saved');refreshPrices(false);});const change=()=>{$('#provider-field').hidden=$('#holding-type').value!=='crypto';$('#quantity-label').textContent=$('#holding-type').value==='gold'?'Weight in grams':'Quantity / units';};$('#holding-type').addEventListener('change',change);change();}
function planModal(){const plan=state.plans[month]||defaultPlan();modal('Plan '+monthLabel(),`<form><p class="form-hint">Amounts in ${cur()}. Enter monthly take-home income and include debt payments in your categories.</p><div class="form-grid"><label>Take-home income<input name="income" required type="number" min="0" max="1000000000000" step="0.01" value="${amountInput(plan.income)}"></label><label>Cash & irregular-bill reserve<input name="reserve" required type="number" min="0" max="1000000000000" step="0.01" value="${amountInput(plan.reserve)}"></label></div><div class="form-divider">EXPECTED MONTHLY SPENDING</div><div class="form-grid">${CATEGORIES.map(c=>`<label>${c.name}<input name="${c.id}" required type="number" min="0" max="1000000000000" step="0.01" value="${amountInput(plan.categories[c.id]||0)}"></label>`).join('')}</div><p class="form-hint">The reserve protects money for emergencies, annual bills, and savings. It is separate from spending.</p><div class="modal-actions"><button type="button" class="button" data-action="close-modal">Cancel</button><button class="button primary" type="submit">Save monthly plan</button></div></form>`,data=>{state.plans[month]={income:preserveAmount(data.income,plan.income,amountInput(plan.income),toAED),reserve:preserveAmount(data.reserve,plan.reserve,amountInput(plan.reserve),toAED),categories:Object.fromEntries(CATEGORIES.map(c=>[c.id,preserveAmount(data[c.id],plan.categories[c.id],amountInput(plan.categories[c.id]),toAED)]))};persist();closeModal();render();notify('Monthly plan saved');});}
function transactionModal(id){const existing=state.transactions.find(t=>t.id===id),t=existing||{date:month===monthNow()?localDate():month+'-01',description:'',amount:0,account:'Main account',category:'other',type:'expense'};modal(existing?'Edit transaction':'Add a transaction',`<form><div class="form-grid"><label>Date<input name="date" type="date" required value="${t.date}"></label><label>Amount (${cur()})<input name="amount" type="number" min="0.01" step="0.01" max="1000000000000" required value="${t.amount?amountInput(t.amount):''}" placeholder="0.00"></label><label class="full">Description<input name="description" required maxlength="500" value="${esc(t.description)}" placeholder="e.g. Groceries at Carrefour"></label><label>Transaction type<select name="type">${options(Object.entries(TYPES),t.type)}</select></label><label>Category<select name="category">${options(CATEGORIES.map(c=>[c.id,c.name]),t.category)}</select></label><label class="full">Account nickname<input name="account" required maxlength="120" value="${esc(t.account)}"></label></div><p class="form-hint">Always enter a positive amount. Refunds reduce spending. Transfers are excluded. Investment contributions reduce your investment runway but don’t change your holdings automatically.</p><div class="modal-actions">${existing?`<button type="button" class="button danger" data-delete-transaction="${id}">${icon('trash-2')} Delete</button>`:'<span></span>'}<button class="button primary" type="submit">Save transaction</button></div></form>`,data=>{const item={...t,id:existing?.id||uid(),date:data.date,description:data.description.trim(),amount:preserveAmount(data.amount,t.amount,amountInput(t.amount),toAED),type:data.type,category:data.category,account:data.account.trim(),source:t.source||'Manual'};if(!validateTransaction(item))throw new Error('Check the date, amount, description, and account.');if(existing)state.transactions=state.transactions.map(x=>x.id===id?item:x);else state.transactions.push(item);persist();closeModal();month=item.date.slice(0,7);render();notify('Transaction saved');});}
function confirmModal(title,message,action,label='Confirm'){modal(title,`<p class="body-copy">${message}</p><div class="modal-actions"><button class="button" data-action="close-modal">Cancel</button><button class="button primary" id="confirm-action">${label}</button></div>`);$('#confirm-action').addEventListener('click',()=>{action();closeModal();render();});}
async function refreshPrices(show=true){if(refreshing||state.isDemo){if(state.isDemo&&show)notify('Example prices stay illustrative. Return to your workspace for live quotes.');return;}refreshing=true;const targetState=state;if(show)render();try{const holdings=state.holdings.map(({id,type,providerId,symbol})=>({id,type,providerId,symbol}));const r=await fetch('/api/quotes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({holdings}),signal:AbortSignal.timeout(40000)});const data=await r.json();if(!r.ok)throw new Error(data.error||'Prices could not refresh');if(state!==targetState)return;for(const h of state.holdings.filter(h=>h.type==='gold')){const old=state.quotes[h.id],q=data.quotes[h.id];if(q&&old?.priceUSD&&q.asOf!==old.asOf){q.change24h=(q.priceUSD/old.priceUSD-1)*100;q.changeBasis='Since prior quote';q.changeFrom=old.asOf;}else if(q&&old){q.change24h=old.change24h??null;q.changeBasis=old.changeBasis;q.changeFrom=old.changeFrom;}}state.quotes={...state.quotes,...data.quotes};quoteErrors=data.errors||{};persist();if(show)notify(Object.keys(quoteErrors).length?'Available quotes updated; some feeds could not refresh.':'Prices updated');}catch(e){if(state!==targetState)return;quoteErrors=Object.fromEntries(state.holdings.map(h=>[h.id,e.message]));if(show)notify('Price refresh unavailable. Previous timestamps are preserved.');}finally{refreshing=false;if(['overview','portfolio'].includes(view)&&!$('dialog')&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))render();}}
function download(name,contents,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([contents],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function exportBackup(){download(`harbour-backup-${localDate()}.json`,JSON.stringify(state,null,2));notify(state.isDemo?'Example backup downloaded':'Backup downloaded');}
function exportCSV(){const quote=x=>'"'+String(x).replace(/"/g,'""')+'"';const rows=[['Date','Description','Amount AED','Type','Category','Account'],...filteredTransactions().map(t=>[t.date,/^[=+@\-\t\r]/.test(t.description)?"'"+t.description:t.description,t.amount,t.type,t.category,/^[=+@\-\t\r]/.test(t.account)?"'"+t.account:t.account])];download(`harbour-transactions-${month}.csv`,rows.map(r=>r.map(quote).join(',')).join('\r\n'),'text/csv');}
function initReview(result){const flags=duplicateFlags(result.rows,state.transactions);review={...result,rows:result.rows.map((t,i)=>({...t,include:!flags[i],reviewed:false}))};render();}
function inferMap(headers){const match=rx=>headers.findIndex(h=>rx.test(h.trim()));return {date:match(/date/i),description:match(/description|narration|details|merchant|particulars/i),amount:match(/^amount|transaction amount/i),debit:match(/debit|withdrawal|money out/i),credit:match(/credit|deposit|money in/i)};}
function parseText(){sourceText=$('#statement-text')?.value||sourceText;if(!sourceText.trim())return notify('Paste your statement text first.');lastFile='Pasted statement';csvTable=null;const lines=sourceText.trim().split('\n');if(lines[0].includes(',')&&/date/i.test(lines[0])){csvTable=parseCSV(sourceText);const mapping=inferMap(csvTable[0]);initReview({...csvTransactions(csvTable,mapping,{...importOptions,fx:state.settings.fx}),mapping});}else initReview(textTransactions(sourceText,{...importOptions,fx:state.settings.fx}));}
async function readStatement(file){if(importBusy||!file)return;if(file.size>20*1024*1024)return notify('Please use a file smaller than 20 MB.');importBusy=true;lastFile=file.name;render();const progress=text=>{const el=$('#import-progress');if(el)el.textContent=text;};try{if(/\.csv$/i.test(file.name)){sourceText=await file.text();csvTable=parseCSV(sourceText);if(csvTable.length<2)throw new Error('This CSV has no transaction rows.');const mapping=inferMap(csvTable[0]);initReview({...csvTransactions(csvTable,mapping,{...importOptions,fx:state.settings.fx}),mapping});}else if(/\.txt$/i.test(file.name)){sourceText=await file.text();csvTable=null;initReview(textTransactions(sourceText,{...importOptions,fx:state.settings.fx}));}else{progress('Preparing local text recognition…');const {extractStatement}=await import('./statement-reader.js');sourceText=await extractStatement(file,progress);csvTable=null;initReview(textTransactions(sourceText,{...importOptions,fx:state.settings.fx}));}}catch(e){notify(e.message||'The statement could not be read. Try a CSV export or paste its text.');}finally{importBusy=false;render();}}
function commitImport(){const selected=review.rows.filter(t=>t.include!==false);if(!selected.length)return notify('Include at least one transaction.');if(!selected.every(t=>t.reviewed))return notify('Check every included row against the statement, then mark it checked.');if(!selected.every(validateTransaction))return notify('A row contains an invalid date, amount, or description. Correct it before importing.');const apply=()=>{state.transactions.push(...selected.map(({include,reviewed,rawLine,uncertain,...t})=>t));state.imports.push({name:lastFile||'Pasted statement',at:new Date().toISOString(),count:selected.length});month=selected.map(t=>t.date).sort().at(-1).slice(0,7);persist();review=null;csvTable=null;sourceText='';changeView('transactions');notify(`${selected.length} transactions added`);};const duplicates=duplicateFlags(selected,state.transactions).filter(Boolean).length;if(duplicates)confirmModal('Keep possible duplicates?',`${duplicates} included transaction(s) match another entry by date, amount, description, type, and account. Keep them only if they are separate real charges.`,apply,'Keep and import');else apply();}
function changeView(next,{updateHistory=true}={}){if(!viewIds.includes(next))next='overview';if(importBusy&&next!=='import')notify('Statement reading continues locally. Return to Import statements to review.');const changed=view!==next;view=next;if(updateHistory&&location.hash!==`#${next}`)history.pushState({view:next},'',`#${next}`);if(changed){window.scrollTo(0,0);render();}}
function syncViewFromLocation(){changeView(routeView(),{updateHistory:false});}
document.addEventListener('click',e=>{
 const currency=e.target.closest('[data-currency]');if(currency){state.settings.currency=currency.dataset.currency;persist();render();return;}
 const nav=e.target.closest('[data-view]');if(nav){e.preventDefault();changeView(nav.dataset.view);return;}
 const filter=e.target.closest('[data-filter]');if(filter){assetFilter=filter.dataset.filter;render();return;}
 const range=e.target.closest('[data-range]');if(range){chartRange=range.dataset.range;render();return;}
 const eh=e.target.closest('[data-edit-holding]');if(eh)return holdingModal(eh.dataset.editHolding);
 const et=e.target.closest('[data-edit-transaction]');if(et)return transactionModal(et.dataset.editTransaction);
 const dh=e.target.closest('[data-delete-holding]');if(dh)return confirmModal('Remove this holding?','This removes the holding from your portfolio and watchlist. It does not change budget transactions.',()=>{state.holdings=state.holdings.filter(h=>h.id!==dh.dataset.deleteHolding);persist();},'Remove holding');
 const dt=e.target.closest('[data-delete-transaction]');if(dt)return confirmModal('Delete this transaction?','Your monthly spending will be recalculated without this transaction.',()=>{state.transactions=state.transactions.filter(t=>t.id!==dt.dataset.deleteTransaction);persist();},'Delete transaction');
 const a=e.target.closest('[data-action]')?.dataset.action;if(!a)return;if(importBusy&&['demo','exit-demo','reset','parse-text'].includes(a))return notify('Please wait for the current statement to finish reading.');
 if(a==='close-modal')closeModal();else if(a==='add-holding')holdingModal();else if(a==='add-transaction')transactionModal();else if(a==='edit-plan')planModal();else if(a==='refresh')refreshPrices();else if(a==='backup')exportBackup();else if(a==='export-csv')exportCSV();else if(a.startsWith('go-'))changeView(a.slice(3));
 else if(a==='prev-month'||a==='next-month'){const d=new Date(month+'-15T12:00:00');d.setMonth(d.getMonth()+(a==='next-month'?1:-1));month=localDate(d).slice(0,7);render();}
 else if(a==='retry-history'){const h=state.holdings.find(h=>h.id===chartAsset);if(h)histories.delete(`${h.marketSymbol||h.symbol}:${chartRange}`);render();}
 else if(a==='demo'){if(state.isDemo)return;if(review)return notify('Finish or discard the pending statement review before opening an example.');realState=structuredClone(state);state=demoState();quoteErrors={};changeView('overview');render();notify('Example workspace opened. Your saved data is separate.');}
 else if(a==='exit-demo'){state=realState||freshState();realState=null;review=null;csvTable=null;sourceText='';render();refreshPrices(false);}
 else if(a==='copy-plan'){const d=new Date(month+'-15T12:00:00');d.setMonth(d.getMonth()-1);const prior=state.plans[localDate(d).slice(0,7)];if(!prior)return notify('No budget plan exists for the previous month.');const apply=()=>{state.plans[month]=structuredClone(prior);persist();notify('Previous month’s plan copied');};if(state.plans[month])confirmModal('Replace this month’s plan?','Copying the previous month replaces your planned amounts. Actual transactions stay in place.',apply,'Copy plan');else{apply();render();}}
 else if(a==='parse-text')parseText();
 else if(a==='discard-review')confirmModal('Discard this review?','These candidate transactions have not been added to your budget.',()=>{review=null;csvTable=null;sourceText='';},'Discard review');
 else if(a==='check-review'){review.rows.forEach(t=>{if(t.include!==false)t.reviewed=true;});render();}
 else if(a==='add-review-row'){review.rows.push({id:uid(),date:localDate(),description:'',amount:0,type:'expense',category:'other',account:importOptions.account,source:'Statement',include:true,reviewed:false});render();}
 else if(a==='remap'){const mapping={...review.mapping};initReview({...csvTransactions(csvTable,mapping,{...importOptions,fx:state.settings.fx}),mapping});}
 else if(a==='commit-import')commitImport();
 else if(a==='reset'){modal('Reset your workspace',`<form><p class="body-copy">Export a backup first if you want to keep your data. This removes all saved plans and transactions, and restores the starter watchlist.</p><label>Type RESET to confirm<input name="confirm" required pattern="RESET" autocomplete="off"></label><div class="modal-actions"><button type="button" class="button" data-action="close-modal">Cancel</button><button class="button danger" type="submit">Reset workspace</button></div></form>`,()=>{state=freshState();realState=null;review=null;storageBlocked=false;persist();closeModal();changeView('overview');render();refreshPrices(false);});}
});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='chart-asset'){chartAsset=el.value;render();}else if(el.id==='month-select'&&el.value){month=el.value;render();}else if(el.id==='transaction-type'){txType=el.value;render();}else if(el.id==='import-currency')importOptions.currency=el.value;else if(el.id==='import-account')importOptions.account=el.value.trim()||'Main account';else if(el.id==='import-date')importOptions.dateOrder=el.value;else if(el.id==='positive-direction')importOptions.positive=el.value;else if(el.dataset.map)review.mapping[el.dataset.map]=Number(el.value);else if(el.id==='statement-file')readStatement(el.files[0]);else if(el.dataset.review!==undefined){const t=review.rows[Number(el.dataset.review)],field=el.dataset.field;t[field]=field==='amount'?toAED(Number(el.value)):['include','reviewed'].includes(field)?el.checked:el.value;if(!['reviewed','include'].includes(field)){t.reviewed=false;const check=el.closest('tr').querySelector('[data-field=reviewed]');if(check)check.checked=false;const included=review.rows.filter(r=>r.include!==false),total=sum(included.filter(r=>r.type==='expense').map(r=>r.amount))-sum(included.filter(r=>r.type==='refund').map(r=>r.amount));const summary=$('.review-footer b');if(summary)summary.textContent=`${included.length} included · ${money(total)} net spending`;}else render();}else if(el.id==='restore-file'){try{const file=el.files[0];if(!file)return;if(file.size>20*1024*1024)throw new Error('Backup is too large.');const restored=validateState(JSON.parse(await file.text()));confirmModal('Restore this backup?',`This replaces your current workspace with ${restored.holdings.length} holdings and ${restored.transactions.length} transactions. Export your current data first if you need it.`,()=>{state=restored;realState=null;review=null;storageBlocked=false;persist();notify('Backup restored');refreshPrices(false);},'Restore backup');}catch(e){notify(e.message);}}});
document.addEventListener('input',e=>{if(e.target.dataset.review!==undefined){const el=e.target,t=review.rows[Number(el.dataset.review)],field=el.dataset.field;if(['amount','description','date'].includes(field)){t[field]=field==='amount'?toAED(Number(el.value)):el.value;t.reviewed=false;const check=el.closest('tr').querySelector('[data-field=reviewed]');if(check)check.checked=false;const included=review.rows.filter(r=>r.include!==false),total=sum(included.filter(r=>r.type==='expense').map(r=>r.amount))-sum(included.filter(r=>r.type==='refund').map(r=>r.amount));const summary=$('.review-footer b');if(summary)summary.textContent=`${included.length} included · ${money(total)} net spending`;}}else if(e.target.id==='transaction-search'){query=e.target.value;const pos=e.target.selectionStart;render();const input=$('#transaction-search');input.focus();input.setSelectionRange(pos,pos);}else if(e.target.id==='statement-text')sourceText=e.target.value;});
document.addEventListener('submit',e=>{if(e.target.id==='settings-form'){e.preventDefault();const f=e.target;if(!f.reportValidity())return;const data=new FormData(f);state.settings={currency:data.get('currency'),fx:Number(data.get('fx')),autoRefresh:data.has('autoRefresh')};persist();render();notify('Preferences saved');}});
document.addEventListener('dragover',e=>{if(e.target.closest('#drop-zone')){e.preventDefault();$('#drop-zone').classList.add('dragover');}});
document.addEventListener('dragleave',e=>e.target.closest('#drop-zone')?.classList.remove('dragover'));
document.addEventListener('drop',e=>{if(e.target.closest('#drop-zone')){e.preventDefault();readStatement(e.dataTransfer.files[0]);}});
window.addEventListener('popstate',syncViewFromLocation);
window.addEventListener('hashchange',syncViewFromLocation);
window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue||state.isDemo)return;try{const incoming=JSON.parse(e.newValue),next=validateState(incoming);next.quotes=incoming.quotes||{};state=next;if(!$('dialog')&&!review&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))render();}catch{notify('Another tab saved data that could not be read. Export a backup before continuing.');}});
setInterval(()=>{if(state.settings.autoRefresh&&!document.hidden&&!state.isDemo&&!$('dialog')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))refreshPrices(false);},300000);
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const defs=[{name:'read_financial_summary',description:'Read the displayed portfolio and selected month budget summary. Does not change records.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('No input fields are accepted.');const {rows,...budget}=monthlySummary(state,month);return {currency:cur(),month,portfolioUSD:portfolioSummary(state),budgetAED:budget,transactionCount:rows.length,example:!!state.isDemo};}},{name:'start_statement_review',description:'Open the local statement import screen. Does not upload a file or create transactions.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('No input fields are accepted.');changeView('import');return {screen:'import',pendingReview:!!review};}}];for(const d of defs)try{Promise.resolve(context.registerTool(d)).catch(()=>{});}catch{}}
render();registerTools();refreshPrices(false);
